CREATE TABLE duels (id TEXT PRIMARY KEY NOT NULL, a_id TEXT NOT NULL, b_id TEXT NOT NULL, status TEXT NOT NULL, a_hp INTEGER NOT NULL DEFAULT 30, b_hp INTEGER NOT NULL DEFAULT 30, a_heals INTEGER NOT NULL DEFAULT 3, b_heals INTEGER NOT NULL DEFAULT 3, turn TEXT NOT NULL DEFAULT '', log TEXT NOT NULL DEFAULT '[]', winner TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX duels_a ON duels (a_id);
CREATE INDEX duels_b ON duels (b_id);
